import java.text.DecimalFormat;
import java.util.Scanner;
public class JWinPercentage {
	public static void main(String[] args) {
		//Paso 1: Definir e inicializar la variable para almacenar el numero total de partidos en el torneo
		int totalGames = 12;
		//Paso 2: Leer el numero que ingresa el usuario
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el numero de partidos que el equipo gano en el torneo: ");
		int wins = scan.nextInt();		
		//Paso 3: Validar la entrada del usuario, pedir una entrada valida mientras el usuario ingrese un numero invalido; de lo contrario detener
		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Ingrese el numero de partidos que el equipo gano en el torneo: ");
			wins = scan.nextInt();
		}
		scan.close();
		//Paso 4: Calcular e imprimir el porcentaje de partidos ganados por el equipo
		double ratio = (double) wins / totalGames;
		DecimalFormat fmt = new DecimalFormat("0.###");
		System.out.println("Porcentaje de victorias:" + fmt.format(ratio));
	}
}

