import java.text.DecimalFormat;
import java.util.Scanner;
public class JWinPercentage {
	public static void main(String[] args) {
		//Step 1: Define and initialize the variable for storing the total number of games in the tournament
		int totalGames = 12;
		//Step 2: Read the number that the user enters
		Scanner scan = new Scanner(System.in);
		System.out.println("Enter the number of games that the sports team won in the tournament: ");
		int wins = scan.nextInt();		
		//Step 3: Validate the user input, ask for a valid input as long as the user enters an invalid number; otherwise stop
		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Enter the number of games that the sports team won in the tournament: ");
			wins = scan.nextInt();
		}
		scan.close();
		//Step 4: Calculate and print the percentage of games won by a team
		double ratio = (double) wins / totalGames;
		DecimalFormat fmt = new DecimalFormat("0.###");
		System.out.println("Winning percentage:" + fmt.format(ratio));
	}
}
